CREATE OR REPLACE FUNCTION public.admin_delete_customer_credential(p_owner uuid,p_credential uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE removed_id uuid; BEGIN IF NOT public.has_any_role(auth.uid(),ARRAY['admin','management']::public.app_role[]) THEN RAISE EXCEPTION 'Forbidden'; END IF; DELETE FROM private.app_credentials WHERE id=p_credential AND owner_id=p_owner RETURNING id INTO removed_id; IF removed_id IS NULL THEN RAISE EXCEPTION 'Login was not found for this customer'; END IF; INSERT INTO public.credential_change_events(credential_id,owner_id) VALUES(removed_id,p_owner); RETURN true; END $$; REVOKE ALL ON FUNCTION public.admin_delete_customer_credential(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_delete_customer_credential(uuid,uuid) TO authenticated;